(
  /* Получаем идентификатор аспекта для карточки */
  $aspect_id := $params."dh-aspect-id";

  /* Получаем виджеты, которые нужно отобразить */
  $widgets := entities.aspects.presentations.blank.widgets;
  $wleft := $widgets.*[align="<"]^(order);
  $wright := $widgets.*[align=">"]^(order);
  $wcenter := $widgets.*[$not(align=">" or align="<")]^(order);

  /* Функция генерации  профиля виджета для секции разметки */
  $makeWidget := function($widgets) {(
    [$widgets.{
        "title": title,
        "icon": icon,
        "style": style ? style : {},
        "src": "@entity/aspects/" & presentation & "?aspect=" & $aspect_id
    }];
  )};

  /* Строим разметку страницы */
  {
    "type": "rows",
    "items": $append(
      [
        {
          "type": "columns",
          "items": [
            {
              "type": "rows",
              "width": "40%",
              /* Строим список виджетов левой секции */
              "items": $makeWidget($wleft)
            },
            {
              "type": "rows",
              "width": "60%",
              /* Строим список виджетов правой секции */
              "items": $makeWidget($wright)
            }
          ]
        }
      ],
      /* Добавляем центральные виджеты */
      $makeWidget($wcenter)
    )
  }
)

hierarchy.source:
(
  $ASPECTS := aspects;
  /* Определяем фильтр для выделяемой иерархической структуры */
  $FILTER := $params.aspect;
  $FILTER_LN := $length($FILTER);
  /* Определяем иерархию владельцев */
  $PARENTS := $FILTER.$split(".")~>$map(function($v, $LIMIT, $a){(
      $a~>$map(function($v, $i) { $i <= $LIMIT ? $v})~>$join(".");
  )});
  $merge((
      /* Выбираем их компонентов нужные для построения диаграммы */
      [$ASPECTS.$spread().(
            $ID := $keys()[0];
            $PREFIX := $substring($ID, 0, $FILTER_LN + 1);
            $FILTER_LN = 0
            or ($PREFIX = $FILTER) or ($PREFIX = ($FILTER & "."))
            or ($ID in $PARENTS) ? $ID;
        )]
      ).(
        /* Готовим полный массив идентификаторов */
        ($~>$split(".")~>$map(function($v, $limit, $struct) {
          {
            $struct~>$map(function($pice, $index) {
              $index <= $limit ? $pice
            })~>$join("."): true
          }
        }))
    )
  ).$spread().(
    /* Готовим массив для вывода */
    $ID := $keys()[0];
    $ASPECT := $lookup($ASPECTS, $ID);
    {
      "id": $ID,
      "title": $ASPECT.title ? $ASPECT.title : $ID,
      "link": $CONTEXT ? "/architect/aspects/" & $ID : "/architect/aspects/" & $ID
    }            
  )^(id).(
    /* Готовим PlantUML код для MindMap */
    $color := id = $FILTER ? "[#FFBBCC]" : "";
    $content := id = title ? " " & title : " [[" & link & " " & title & "]]";
    "*" & $join($split(id, ".").("*")) & $color & $content
  )~>$join("\n");
)

